use crate::requests::headers::insert_header;
use crate::requests::headers::subagent_header;
use crate::sse::spawn_chat_stream;
use crate::sse::spawn_response_stream;
use crate::telemetry::SseTelemetry;
use codex_client::EncodedJsonBody;
use codex_client::HttpTransport;
use codex_client::RequestCompression;
use codex_client::RequestTelemetry;
use codex_protocol::protocol::SessionSource;
use http::HeaderMap;
use http::HeaderValue;
use http::Method;
use serde_json::Value;
use std::sync::Arc;
use std::sync::OnceLock;
use tracing::instrument;

/// Responses-compatible inference routes supported by Suffice backend.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ResponsesEndpoint {
    /// Regular user-owned model inference.
    #[default]
    Responses,
    /// Full Guardian approval-review agent inference.
    Guardian,
    /// Lightweight asynchronous Guardian risk classification.
    GuardianClassifier,
}

impl ResponsesEndpoint {
    /// Returns the provider-relative path for this inference surface.
    pub const fn path(self) -> &'static str {
        match self {
            Self::Responses => "/responses",
            Self::Guardian => "/guardian",
            Self::GuardianClassifier => "/guardian-classifier",
        }
    }
}

pub struct ResponsesClient<T: HttpTransport> {
    session: EndpointSession<T>,
    sse_telemetry: Option<Arc<dyn SseTelemetry>>,
    endpoint: ResponsesEndpoint,
}

#[derive(Default)]
pub struct ResponsesOptions {
    pub session_id: Option<String>,
    pub thread_id: Option<String>,
    pub session_source: Option<SessionSource>,
    pub extra_headers: HeaderMap,
    pub compression: Compression,
    pub turn_state: Option<Arc<OnceLock<String>>>,
    /// Receives the body that actually went on the wire.
    ///
    /// The prompt-cache keep-alive replays it verbatim while the session is
    /// idle; rebuilding it later would cost a second full translation pass.
    /// Only filled for [`WireApi::Chat`], the one wire whose cache is keyed by
    /// the literal message prefix.
    pub sent_body: Option<Arc<OnceLock<Value>>>,
}

impl<T: HttpTransport> ResponsesClient<T> {
    pub fn new(transport: T, provider: Provider, auth: SharedAuthProvider) -> Self {
        Self {
            session: EndpointSession::new(transport, provider, auth),
            sse_telemetry: None,
            endpoint: ResponsesEndpoint::Responses,
        }
    }

    /// Selects a Responses-compatible backend route for subsequent requests.
    pub fn with_endpoint(mut self, endpoint: ResponsesEndpoint) -> Self {
        self.endpoint = endpoint;
        self
    }

    pub fn with_telemetry(
        self,
        request: Option<Arc<dyn RequestTelemetry>>,
        sse: Option<Arc<dyn SseTelemetry>>,
    ) -> Self {
        Self {
            session: self.session.with_request_telemetry(request),
            sse_telemetry: sse,
            endpoint: self.endpoint,
        }
    }

    #[instrument(
        name = "responses.stream_request",
        level = "info",
        skip_all,
        fields(
            transport = "responses_http",
            http.method = "POST",
            api.path = self.endpoint.path()
        )
    )]
    pub async fn stream_request(
        &self,
        request: ResponsesApiRequest,
        options: ResponsesOptions,
    ) -> Result<ResponseStream, ApiError> {
        let ResponsesOptions {
            session_id,
            thread_id,
            session_source,
            extra_headers,
            compression,
            turn_state,
            sent_body,
        } = options;

        // Chat-only providers get the request rewritten here and their SSE
        // frames rewritten back, so nothing above this call site is aware of
        // the wire difference.
        let body = match self.session.provider().wire {
            WireApi::Responses => EncodedJsonBody::encode(&request),
            WireApi::Chat => {
                let chat_body = chat_body_from_responses_request(&request);
                let encoded = EncodedJsonBody::encode(&chat_body);
                if let Some(slot) = sent_body {
                    let _ = slot.set(chat_body);
                }
                encoded
            }
        }
        .map_err(|e| ApiError::Stream(format!("failed to encode responses request: {e}")))?;

        let mut headers = extra_headers;
        if let Some(ref thread_id) = thread_id {
            insert_header(&mut headers, "x-client-request-id", thread_id);
        }
        headers.extend(build_session_headers(session_id, thread_id));
        if let Some(subagent) = subagent_header(&session_source) {
            insert_header(&mut headers, "x-openai-subagent", &subagent);
        }

        self.stream_encoded(body, headers, compression, turn_state)
            .await
    }

    #[instrument(
        name = "responses.stream",
        level = "info",
        skip_all,
        fields(
            transport = "responses_http",
            http.method = "POST",
            api.path = self.endpoint.path(),
            turn.has_state = turn_state.is_some()
        )
    )]
    pub async fn stream(
        &self,
        body: Value,
        extra_headers: HeaderMap,
        compression: Compression,
        turn_state: Option<Arc<OnceLock<String>>>,
    ) -> Result<ResponseStream, ApiError> {
        let body = EncodedJsonBody::encode(&body)
            .map_err(|e| ApiError::Stream(format!("failed to encode responses request: {e}")))?;
        self.stream_encoded(body, extra_headers, compression, turn_state)
            .await
    }

    async fn stream_encoded(
        &self,
        body: EncodedJsonBody,
        extra_headers: HeaderMap,
        compression: Compression,
        turn_state: Option<Arc<OnceLock<String>>>,
    ) -> Result<ResponseStream, ApiError> {
        let request_compression = match compression {
            Compression::None => RequestCompression::None,
            Compression::Zstd => RequestCompression::Zstd,
        };

        let wire = self.session.provider().wire;
        let path = match wire {
            WireApi::Responses => self.endpoint.path(),
            WireApi::Chat => "/chat/completions",
        };

        let stream_response = self
            .session
            .stream_encoded_json_with(
                Method::POST,
                path,
                extra_headers,
                Some(body),
                |req| {
                    req.headers.insert(
                        http::header::ACCEPT,
                        HeaderValue::from_static("text/event-stream"),
                    );
                    req.compression = request_compression;
                },
            )
            .await?;

        let idle_timeout = self.session.provider().stream_idle_timeout;
        Ok(match wire {
            WireApi::Responses => spawn_response_stream(
                stream_response,
                idle_timeout,
                self.sse_telemetry.clone(),
                turn_state,
            ),
            WireApi::Chat => {
                spawn_chat_stream(stream_response, idle_timeout, self.sse_telemetry.clone())
            }
        })
    }
}

