102:                                 let _ = tx_result.send(result);
103:                                 if should_break {
104:                                     break;
105:                                 }
106:                             }
107:                             WsCommand::Close { tx_result } => {
108:                                 info!("realtime websocket sending close");
109:                                 let result = inner.close(None).await;
110:                                 if let Err(err) = &result {
111:                                     error!("realtime websocket close failed: {err}");
112:                                 }
113:                                 let _ = tx_result.send(result);
114:                                 break;
115:                             }
116:                         }
117:                     }
118:                     message = inner.next() => {
119:                         let Some(message) = message else {
120:                             break;
121:                         };
122:                         match message {
123:                             Ok(Message::Ping(payload)) => {
124:                                 trace!(payload_len = payload.len(), "realtime websocket received ping");
125:                                 if let Err(err) = inner.send(Message::Pong(payload)).await {
126:                                     error!("realtime websocket failed to send pong: {err}");
127:                                     let _ = tx_message.send(Err(err)).await;
128:                                     break;
129:                                 }
130:                             }
131:                             Ok(Message::Pong(_)) => {}
132:                             Ok(message @ (Message::Text(_)
133:                                 | Message::Binary(_)
134:                                 | Message::Close(_)
135:                                 | Message::Frame(_))) => {
136:                                 let is_close = matches!(message, Message::Close(_));
137:                                 match &message {
138:                                     Message::Text(_) => trace!("realtime websocket received text frame"),
