150:                                     Message::Frame(_) => {
151:                                         trace!("realtime websocket received raw frame");
152:                                     }
153:                                     Message::Ping(_) | Message::Pong(_) => {}
154:                                 }
155:                                 if tx_message.send(Ok(message)).await.is_err() {
156:                                     break;
157:                                 }
158:                                 if is_close {
